<script setup>
import{ref,onMounted,onBeforeUnmount}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{apiClient,currentApiCacheScope}from'../../utils/api.js';import{wbPublishStatus,wbPublishPhase}from'../../../../src/shared/wb-publish-status.js';import{shanghaiDateTimeText}from'../../utils/shanghai-date.js';
const rows=ref([]),loading=ref(false),selected=ref(null);let timer,generation=0;
async function load(){const id=++generation,scope=currentApiCacheScope();loading.value=true;try{const r=await apiClient.get('/api/wb/publish-jobs',{noCache:true});if(id!==generation||scope!==currentApiCacheScope())return;rows.value=r.rows;selected.value=selected.value?r.rows.find(row=>Number(row.id)===Number(selected.value.id))||null:null;clearTimeout(timer);if(rows.value.some(row=>['queued','processing'].includes(row.status)))timer=setTimeout(load,10000);}catch(e){if(id===generation)ElMessage.error(e.message);}finally{if(id===generation)loading.value=false;}}
async function resume(job,retry=false){try{await ElMessageBox.confirm(retry?'将重新提交当前媒体或价格，商品卡不会重复创建。':'将核对当前商品和平台结果，并从未完成步骤继续。','继续发布核对',{type:'warning'});}catch{return;}const scope=currentApiCacheScope();try{await apiClient.post('/api/wb/listing-publish/resume',{job_id:job.id,retry});if(scope===currentApiCacheScope())await load();}catch(e){if(scope===currentApiCacheScope())ElMessage.error(e.message);}}
function reset(){generation++;clearTimeout(timer);rows.value=[];selected.value=null;load();}
onMounted(()=>{load();window.addEventListener('erp:auth-scope-changed',reset);});onBeforeUnmount(()=>{generation++;clearTimeout(timer);window.removeEventListener('erp:auth-scope-changed',reset);});
</script>
<template><div class="wb-publish-records"><div class="records-header"><h3>WB 上架记录</h3><el-button :loading="loading" @click="load">刷新结果</el-button></div><el-table :data="rows" v-loading="loading" border stripe empty-text="暂无 WB 发布记录"><el-table-column prop="id" label="记录号" width="90"/><el-table-column prop="shop_name" label="店铺" width="200"/><el-table-column label="商品" min-width="300"><template #default="{row}"><p v-for="item in row.state.items" :key="item.vendor_code">{{item.vendor_code}}<small v-if="item.nm_id"> · WB {{item.nm_id}}</small></p></template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}">{{wbPublishStatus(row.status)}}</template></el-table-column><el-table-column prop="message" label="处理结果" min-width="330"/><el-table-column label="更新（北京）" width="180"><template #default="{row}">{{shanghaiDateTimeText(row.updated_at,{assumeUtcWhenNaive:true})}}</template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button link type="primary" @click="selected=row">详情</el-button><el-button v-if="['needs_review','paused'].includes(row.status)" link @click="resume(row)">继续核对</el-button></template></el-table-column></el-table>
<el-drawer v-if="selected" :model-value="true" title="WB 发布详情" size="min(900px,95vw)" @close="selected=null"><el-alert :title="wbPublishStatus(selected.status)+'：'+selected.message" :closable="false"/><p>店铺：{{selected.shop_name}}</p><p>币种：{{selected.payload.currency}} · 草稿版本 {{selected.draft_revision}}</p><section v-for="(item,index) in selected.state.items" :key="item.vendor_code"><h4>{{selected.payload.variants?.[index]?.card?.title||selected.payload.card?.title}}</h4><p>{{item.vendor_code}} · {{wbPublishPhase(item.phase)}} · {{item.nm_id?'WB '+item.nm_id:'等待商品编号'}}</p><pre v-if="item.price_errors?.length">{{JSON.stringify(item.price_errors,null,2)}}</pre></section><el-button v-if="['needs_review','paused'].includes(selected.status)" @click="resume(selected)">继续核对</el-button><el-button v-if="selected.status==='needs_review'&&['media','price'].includes(selected.state.items.find(item=>item.phase!=='done')?.phase)" type="warning" @click="resume(selected,true)">重试当前媒体或价格</el-button></el-drawer></div></template>
<style scoped>.wb-publish-records{display:grid;gap:16px}.records-header{display:flex;justify-content:space-between;align-items:center}.wb-publish-records p{margin:5px 0}.wb-publish-records small{color:var(--el-text-color-secondary)}</style>
